"use client";

import { cn } from "@/lib/utils";
import type { Variants } from "motion/react";
import {
 LazyMotion,
 domMin,
 m,
 useAnimation,
 useReducedMotion,
} from "motion/react";
import {
 forwardRef,
 useCallback,
 useImperativeHandle,
 useRef,
 type HTMLAttributes,
} from "react";
export interface ShoppingBasketIconHandle {
 startAnimation: () => void;
 stopAnimation: () => void;
}

interface ShoppingBasketIconProps extends Omit<
 HTMLAttributes<HTMLDivElement>,
 | "color"
 | "onDrag"
 | "onDragStart"
 | "onDragEnd"
 | "onAnimationStart"
 | "onAnimationEnd"
 | "onAnimationIteration"
> {
 size?: number;
 duration?: number;
 isAnimated?: boolean;
 color?: string;
}

const ShoppingBasketIcon = forwardRef<
 ShoppingBasketIconHandle,
 ShoppingBasketIconProps
>(
 (
  {
   onMouseEnter,
   onMouseLeave,
   className,
   size = 24,
   duration = 1,
   isAnimated = true,
   color,
   ...props
  },
  ref,
 ) => {
  const controls = useAnimation();
  const reduced = useReducedMotion();
  const isControlled = useRef(false);

  useImperativeHandle(ref, () => {
   isControlled.current = true;
   return {
    startAnimation: () =>
     reduced ? controls.start("normal") : controls.start("animate"),
    stopAnimation: () => controls.start("normal"),
   };
  });

  const handleEnter = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isAnimated || reduced) return;
    if (!isControlled.current) controls.start("animate");
    else onMouseEnter?.(e as any);
   },
   [controls, reduced, isAnimated, onMouseEnter],
  );

  const handleLeave = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isControlled.current) controls.start("normal");
    else onMouseLeave?.(e as any);
   },
   [controls, onMouseLeave],
  );

  const handleVariants = (angle: number): Variants => ({
   normal: { rotate: 0 },
   animate: {
    rotate: [0, angle, -angle * 0.65, angle * 0.25, 0],
    transition: { duration: 0.8 * duration, ease: "easeInOut" },
   },
  });

  const basketVariants: Variants = {
   normal: { scaleY: 1 },
   animate: {
    scaleY: [1, 0.95, 1.02, 1],
    transition: {
     duration: 0.6 * duration,
     ease: "easeInOut",
     times: [0, 0.35, 0.7, 1],
    },
   },
  };

  return (
   <LazyMotion features={domMin} strict>
    <m.div
     className={cn("inline-flex items-center justify-center", className)}
     onMouseEnter={handleEnter}
     onMouseLeave={handleLeave}
     {...props}
     style={{ color, ...props.style }}
    >
     <m.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      animate={controls}
      initial="normal"
     >
      <m.path
       d="m19 11-4-7"
       variants={handleVariants(12)}
       style={{ transformBox: "view-box", originX: "19px", originY: "11px" }}
      />
      <m.path
       d="m5 11 4-7"
       variants={handleVariants(-12)}
       style={{ transformBox: "view-box", originX: "5px", originY: "11px" }}
      />
      <m.g
       variants={basketVariants}
       style={{ transformBox: "view-box", originX: "12px", originY: "20px" }}
      >
       <path d="m15 11-1 9" />
       <path d="M2 11h20" />
       <path d="m3.5 11 1.6 7.4a2 2 0 0 0 2 1.6h9.8a2 2 0 0 0 2-1.6l1.7-7.4" />
       <path d="M4.5 15.5h15" />
       <path d="m9 11 1 9" />
      </m.g>
     </m.svg>
    </m.div>
   </LazyMotion>
  );
 },
);

ShoppingBasketIcon.displayName = "ShoppingBasketIcon";
export { ShoppingBasketIcon };
